            return demands.get(i, 0) or 0
        if isinstance(demands, list):
            if 0 <= i < len(demands):
                return demands[i] or 0
        return 0

    coords = safe_attr(instance, "coords", None)
    if coords is None:
        coords = safe_attr(instance, "locations", None)
    if coords is None:
        coords = safe_attr(instance, "points", None)

    demands = safe_attr(instance, "demands", None)
    if demands is None:
        demands = safe_attr(instance, "demand", None)

    capacity = safe_attr(instance, "capacity", None)
    if capacity is None:
        capacity = safe_attr(instance, "vehicle_capacity", None)
    if capacity is None:
        capacity = safe_attr(instance, "cap", None)
    if capacity is None:
        capacity = 0
    try:
        capacity = float(capacity)
    except:
        capacity = 0.0

    depot = safe_attr(instance, "depot", 0)

    if isinstance(coords, dict):
        node_ids = list(coords.keys())
    elif isinstance(demands, dict):
        node_ids = list(demands.keys())
    elif isinstance(coords, list):
        node_ids = list(range(len(coords)))
    elif isinstance(demands, list):
        node_ids = list(range(len(demands)))
    else:
        n = safe_attr(instance, "n", None)
        if n is None:
            n = safe_attr(instance, "num_nodes", 0)
        try:
            n = int(n)
        except:
            n = 0
        node_ids = list(range(n))

    if depot not in node_ids:
        if 0 in node_ids:
            depot = 0
        elif node_ids:
            depot = node_ids[0]

    customers = [i for i in node_ids if i != depot]

    def dist(a, b):
        if a == b:
            return 0.0
        xa, ya = coord_of(a, coords)
        xb, yb = coord_of(b, coords)
        dx = xa - xb
        dy = ya - yb
        return (dx * dx + dy * dy) ** 0.5

    def route_load(r):
        s = 0.0
        for c in r:
            s += demand_of(c, demands)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        total = dist(depot, r[0])
        for k in range(len(r) - 1):
            total += dist(r[k], r[k + 1])
        total += dist(r[-1], depot)
        return total

    # Start with singleton routes.
    routes = [[c] for c in customers]

    # Clarke-Wright savings merge.
    cust_to_route = {c: idx for idx, c in enumerate(customers)}
    active = [True] * len(routes)
    savings = []
    for idx_i in range(len(customers)):
        i = customers[idx_i]
        for idx_j in range(idx_i + 1, len(customers)):
            j = customers[idx_j]
            s = dist(depot, i) + dist(depot, j) - dist(i, j)
            savings.append((s, i, j))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    for s, i, j in savings:
        ri = cust_to_route.get(i)
        rj = cust_to_route.get(j)
        if ri is None or rj is None or ri == rj:
            continue
        if not active[ri] or not active[rj]:
            continue
        a = routes[ri]
        b = routes[rj]
        merged = None
        if a[-1] == i and b[0] == j:
            merged = a + b
        elif a[0] == i and b[-1] == j:
            merged = b + a
        elif a[0] == i and b[0] == j:
            merged = list(reversed(a)) + b
        elif a[-1] == i and b[-1] == j:
            merged = a + list(reversed(b))
        if merged is None:
            continue
        if route_load(merged) > capacity and capacity > 0:
            continue
        routes[ri] = merged
        active[rj] = False
        for c in merged:
            cust_to_route[c] = ri

    routes = [r for idx, r in enumerate(routes) if active[idx] and r]

    # Ensure coverage.
    seen = set()
    for r in routes:
        for c in r:
            seen.add(c)
    for c in customers:
        if c not in seen:
            routes.append([c])

    # Intra-route 2-opt.
    improved = True
    while improved:
        improved = False
        for ridx in range(len(routes)):
            r = routes[ridx]
            n = len(r)
            if n < 4:
                continue
            base = route_cost(r)
            best = None
            best_delta = 0.0
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    nr = r[:i + 1] + list(reversed(r[i + 1:j + 1])) + r[j + 1:]
                    nc = route_cost(nr)
                    delta = base - nc
                    if delta > best_delta + 1e-12:
                        best_delta = delta
                        best = nr
            if best is not None:
                routes[ridx] = best
                improved = True

        # Relocate moves
        if improved:
            continue
        moved = False
        for i in range(len(routes)):
            if moved:
                break
            for pos in range(len(routes[i])):
                c = routes[i][pos]
                dc = demand_of(c, demands)
                src = routes[i]
                src_removed = src[:pos] + src[pos + 1:]
                if not src_removed:
                    continue
                before_src = route_cost(src)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    dst = routes[j]
                    if capacity > 0 and route_load(dst) + dc > capacity:
                        continue
                    before = before_src + route_cost(dst)
                    for ins in range(len(dst) + 1):
                        new_dst = dst[:ins] + [c] + dst[ins:]
                        after = route_cost(src_removed) + route_cost(new_dst)
                        if before - after > 1e-12:
                            routes[i] = src_removed
                            routes[j] = new_dst
                            improved = True
                            moved = True
                            break
                    if moved:
                        break
                if moved:
                    break

        routes = [r for r in routes if r]

    # Final repair: coverage and capacity split.
    final_routes = []
    seen = set()
    for r in routes:
        rr = []
        for c in r:
            if c not in seen:
                rr.append(c)
                seen.add(c)
        if rr:
            final_routes.append(rr)
    for c in customers:
        if c not in seen:
            final_routes.append([c])

    repaired = []
    for r in final_routes:
        if capacity <= 0:
            repaired.append(r)
            continue
        cur = []
        load = 0.0
        for c in r:
            d = demand_of(c, demands)
            if cur and load + d > capacity + 1e-12:
                repaired.append(cur)
                cur = [c]
                load = d
            else:
                cur.append(c)
                load += d
        if cur:
            repaired.append(cur)

    return repaired
